# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span

class RoundSpansTest(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        spans = [Span(9 * 60 + 2, 17 * 60 + 11)]
        self.assertEqual(round_spans(spans, 15), ["09:00-17:15 (8h 15m)"])

    def test_halfway_rounds_up(self):
        self.assertEqual(round_spans([Span(60, 120 + 7)], 15), ["01:00-02:00 (1h 0m)"])
        self.assertEqual(round_spans([Span(60, 120 + 8)], 15), ["01:00-02:15 (1h 15m)"])

    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45, 120):
            with self.assertRaises(ValueError):
                round_spans([Span(60, 120)], step)

    def test_empty(self):
        self.assertEqual(round_spans([], 15), [])
